query:
PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?eventLabel ?date ?actorLabel ?riskLabel ?score ?assetLabel
WHERE {
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk ;
         tg:impactsAsset ?asset .
  ?actor rdfs:label ?actorLabel .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
  ?asset rdfs:label ?assetLabel .
}
ORDER BY ?date

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?eventLabel ?date ?actorLabel ?riskLabel ?score ?assetLabel
WHERE {
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk ;
         tg:impactsAsset ?asset .
  ?actor rdfs:label ?actorLabel .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
  ?asset rdfs:label ?assetLabel .
  FILTER(?score > 0.7)
}
ORDER BY DESC(?score)

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?eventLabel ?date ?actorLabel ?riskLabel ?score
WHERE {
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk .
  FILTER(?date >= "2026-07-01"^^xsd:date && ?date <= "2026-07-07"^^xsd:date)
  ?actor rdfs:label ?actorLabel .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
}
ORDER BY ?date

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?eventLabel ?date ?riskLabel ?score ?assetLabel
WHERE {
  ?actor rdfs:label "APT-28 Threat Group" .
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk ;
         tg:impactsAsset ?asset .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
  ?asset rdfs:label ?assetLabel .
}
ORDER BY ?date

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?actorLabel (COUNT(DISTINCT ?event) AS ?eventCount)
WHERE {
  ?event a tg:Event ;
         tg:hasActor ?actor .
  ?actor rdfs:label ?actorLabel .
}
GROUP BY ?actorLabel
ORDER BY DESC(?eventCount)

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?riskLabel ?score (COUNT(DISTINCT ?event) AS ?eventCount)
WHERE {
  ?event a tg:Event ;
         tg:hasRisk ?risk .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
}
GROUP BY ?riskLabel ?score
ORDER BY DESC(?eventCount)

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?assetLabel (COUNT(DISTINCT ?event) AS ?eventCount)
WHERE {
  ?event a tg:Event ;
         tg:impactsAsset ?asset .
  ?asset rdfs:label ?assetLabel .
}
GROUP BY ?assetLabel
ORDER BY DESC(?eventCount)

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?assetLabel ?eventLabel ?date
WHERE {
  ?risk rdfs:label "Ransomware Deployment" .
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasRisk ?risk ;
         tg:impactsAsset ?asset .
  ?asset rdfs:label ?assetLabel .
}
ORDER BY ?date

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?actorLabel ?assetLabel (MAX(?score) AS ?maxScore) (COUNT(DISTINCT ?event) AS ?eventCount)
WHERE {
  ?event a tg:Event ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk ;
         tg:impactsAsset ?asset .
  ?actor rdfs:label ?actorLabel .
  ?risk tg:riskScore ?score .
  ?asset rdfs:label ?assetLabel .
}
GROUP BY ?actorLabel ?assetLabel
ORDER BY DESC(?maxScore)

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?timestamp ?eventLabel ?actorLabel ?riskLabel ?score
WHERE {
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:timestamp ?timestamp ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk .
  ?actor rdfs:label ?actorLabel .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
}
ORDER BY ?timestamp

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?processLabel ?status ?invoker ?eventLabel ?riskLabel ?score
WHERE {
  ?process a tg:Process ;
           rdfs:label ?processLabel ;
           tg:processStatus ?status ;
           tg:invokedBy ?invoker ;
           tg:mitigatesEvent ?event .
  ?event rdfs:label ?eventLabel ;
         tg:hasRisk ?risk .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
}
ORDER BY ?status ?processLabel

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?processLabel ?stepNumber ?stepLabel ?owner ?isComplete
WHERE {
  ?process a tg:Process ;
           rdfs:label ?processLabel ;
           tg:hasStep ?step .
  ?step rdfs:label ?stepLabel ;
        tg:stepNumber ?stepNumber ;
        tg:isComplete ?isComplete ;
        tg:assignedTo ?owner .
}
ORDER BY ?processLabel ?stepNumber

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?owner ?processLabel ?stepNumber ?stepLabel
WHERE {
  ?process a tg:Process ;
           rdfs:label ?processLabel ;
           tg:hasStep ?step .
  ?step rdfs:label ?stepLabel ;
        tg:stepNumber ?stepNumber ;
        tg:isComplete "false"^^xsd:boolean ;
        tg:assignedTo ?owner .
}
ORDER BY ?owner ?processLabel ?stepNumber

PREFIX tg: <http://trustgraph.ai/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?eventLabel ?date ?actorLabel ?riskLabel ?score
WHERE {
  ?event a tg:Event ;
         rdfs:label ?eventLabel ;
         tg:eventDate ?date ;
         tg:hasActor ?actor ;
         tg:hasRisk ?risk .
  ?actor rdfs:label ?actorLabel .
  ?risk rdfs:label ?riskLabel ;
        tg:riskScore ?score .
  FILTER(?score > 0.7)
  FILTER NOT EXISTS {
    ?process a tg:Process ;
             tg:mitigatesEvent ?event .
  }
}
ORDER BY DESC(?score)

PREFIX tg: <http://trustgraph.ai/ontology/>

SELECT ?status (COUNT(?process) AS ?count)
WHERE {
  ?process a tg:Process ;
           tg:processStatus ?status .
}
GROUP BY ?status
ORDER BY ?status
